slides=[]
def cue(cid,text):
 if text.startswith('<div class="screen-note">'):return '<div class="screen-note"><span class="cue" data-cue="'+cid+'">'+text.removeprefix('<div class="screen-note">').removesuffix('</div>')+'</span></div>'
 return f'<div class="cue" data-cue="{cid}">{text}</div>'
def head(tag,title):return f'<div class="tag">{tag}</div><h1>{title}</h1>'
def card(cid,kicker,title,body):return '<article class="card"><small>'+kicker+'</small>'+cue(cid,f'<h2>{title}</h2><p>{body}</p>')+'</article>'
def add(title,body,segments,cls=''):slides.append({'title':title,'body':body,'segments':segments,'class':cls})
